		r.NamespaceKey = storage.DefaultNamespace
	}

	if r.Id == "" {
		return nil, errs.ErrInvalid("rollout ID not supplied")
	}

	tx, err := s.db.Begin()
	if err != nil {
		return nil, err
	}

	defer func() {
		if err != nil {
			_ = tx.Rollback()
		}
	}()

	// get current state for rollout
	rollout, err := getRollout(ctx, s.builder.RunWith(tx), r.NamespaceKey, r.Id)
	if err != nil {
		return nil, err
